<template>
  <p v-if="!content" class="text-sm text-muted-foreground italic">
    Content not generated yet - message is in progress.
  </p>
  <!-- SMS bodies are plain text; render verbatim (no markdown/HTML). The recipient's tracking link is
       minted at send time and never stored in content, so a grayed marker shows where it sat. -->
  <p v-else-if="channel === 'sms'" data-testid="message-content-sms" class="text-sm whitespace-pre-wrap">
    <span>{{ smsBody }}</span>
    <span
      v-if="smsLinkMinted"
      class="text-muted-foreground italic"
      title="Each recipient gets their own link. It is not shown because opening it would count as the recipient's click."
      >{{ "\n[recipient's unique tracking link]" }}</span
    >
    <span v-if="smsOptOut" class="text-muted-foreground">{{ smsOptOut }}</span>
  </p>
  <AppMarkdown v-else data-testid="message-content-email" :markdown="content" />
</template>

<script setup lang="ts">
import type { RecruitmentChannel } from '~/client';

const props = defineProps<{
  channel: RecruitmentChannel;
  content: string | null;
  smsOptOutLine: string | null;
  smsLinkMinted: boolean;
}>();

// Split so the link marker can sit between body and opt-out - the real sent order.
const split = computed(() => splitSmsOptOut(props.content, props.smsOptOutLine));
const smsBody = computed(() => split.value.body);
const smsOptOut = computed(() => split.value.optOut);
</script>
