<template>
  <Alert v-if="errorMessage || providerError" variant="destructive" class="mb-4">
    <AlertTitle>Error</AlertTitle>
    <AlertDescription>
      <template v-if="errorMessage">
        <Badge v-if="errorCodeEntry" :variant="errorCodeEntry.variant" size="sm">
          {{ errorCodeEntry.label }}
        </Badge>
        <p v-if="errorCodeEntry?.description" class="text-sm text-muted-foreground mt-1">
          {{ errorCodeEntry.description }}
        </p>
        <CodeBlock v-if="!errorCodeEntry" plain :text="errorMessage" />
      </template>

      <div v-if="providerError" :class="errorMessage ? 'mt-3 pt-3 border-t border-destructive/20' : ''">
        <p v-if="errorMessage" class="text-xs font-medium mb-1">Carrier Detail</p>
        <Badge :variant="providerError.variant" size="sm">{{ providerError.label }}</Badge>
        <p class="text-sm text-muted-foreground mt-1">{{ providerError.description }}</p>
        <a
          :href="providerError.docsUrl"
          target="_blank"
          rel="noopener"
          class="text-sm text-primary hover:underline break-all"
        >
          Twilio error {{ providerError.code }}
        </a>
      </div>
    </AlertDescription>
  </Alert>
</template>

<script setup lang="ts">
import { getMessageErrorCode } from '~/constants/recruitment/messageErrorCodeConfig';
import { getTwilioErrorCode, twilioErrorDocsUrl } from '~/constants/recruitment/twilioErrorCodeConfig';

const props = defineProps<{
  errorMessage: string | null;
  providerErrorCode: string | null;
}>();

const errorCodeEntry = computed(() => (props.errorMessage ? getMessageErrorCode(props.errorMessage) : null));

const providerError = computed(() => {
  const code = props.providerErrorCode;
  if (!code) return null;
  return { code, docsUrl: twilioErrorDocsUrl(code), ...getTwilioErrorCode(code) };
});
</script>
