import type { BadgeVariants } from '~/components/ui/badge';

// Carrier error codes Twilio reports on a failed SMS. Kept apart from the internal error-code map because
// most delivery failures store no internal code at all: only the codes proving a number is structurally
// undeliverable get one, since that stamp permanently stops texting the number and a single bad delivery
// must not condemn it. For every other failure the carrier code is the only detail the message carries.
type TwilioErrorCode = '21211' | '21610' | '21614' | '30003' | '30005' | '30006' | '30007' | '30008' | '30630';

interface TwilioErrorCodeEntry {
  label: string;
  variant: BadgeVariants;
  description: string;
}

export const twilioErrorCodeConfig: Record<TwilioErrorCode, TwilioErrorCodeEntry> = {
  '21211': {
    label: 'Invalid Phone Number',
    variant: 'destructive',
    description: 'The number is not a valid phone number, so nothing was sent. Correct it on the contact.',
  },
  '21610': {
    label: 'Recipient Opted Out',
    variant: 'warning',
    description:
      'The recipient texted STOP, so the carrier blocks every further text to this number. Only the recipient can undo it, by texting START.',
  },
  '21614': {
    label: 'Not a Mobile Number',
    variant: 'destructive',
    description:
      'The number is real but cannot receive texts - it is a landline or another non-mobile line. Reach this contact by email or a phone call.',
  },
  '30003': {
    label: 'Unreachable Handset',
    variant: 'warning',
    description:
      'The phone was off, out of signal, or roaming when the carrier tried to deliver. This is usually temporary, so sending again later often works.',
  },
  '30005': {
    label: 'Unknown Handset',
    variant: 'warning',
    description:
      'The carrier did not recognize the number. It may no longer be in service - but T-Mobile returns this same code for active numbers whose owner has short-code messaging blocked, so it is not proof the number is dead.',
  },
  '30006': {
    label: 'Landline or Unreachable Carrier',
    variant: 'destructive',
    description:
      'The number cannot receive texts, usually because it is a landline. Twilio advises against sending again - reach this contact by email or a phone call.',
  },
  '30007': {
    label: 'Carrier Violation',
    variant: 'destructive',
    description:
      'The carrier filtered the message as spam before it reached the phone. Message wording, links, or send volume can all trigger this.',
  },
  '30008': {
    label: 'Unknown Carrier Error',
    variant: 'destructive',
    description: 'The carrier rejected the message without saying why.',
  },
  '30630': {
    label: 'Recipient Opted Out',
    variant: 'warning',
    description:
      'The recipient texted STOP, so the carrier blocks every further text to this number. Only the recipient can undo it, by texting START.',
  },
};

export function twilioErrorDocsUrl(code: string): string {
  return `https://www.twilio.com/docs/api/errors/${code}`;
}

export function getTwilioErrorCode(code: string): TwilioErrorCodeEntry {
  return (
    twilioErrorCodeConfig[code as TwilioErrorCode] ?? {
      label: code,
      variant: 'destructive',
      description: 'There is no plain-language summary for this code yet - the Twilio page below explains it.',
    }
  );
}
