<template>
  <section class="flex flex-col gap-4">
    <PageTitle :title="pageTitle">
      <template v-if="data">
        <Badge :variant="getChannel(data.channel).variant">
          {{ getChannel(data.channel).label }}
        </Badge>
        <Badge :variant="getMessageStatus(data.effective_status).variant">
          {{ getMessageStatus(data.effective_status).label }}
        </Badge>
        <Badge :variant="getMessageType(data.message_type).variant">
          {{ getMessageType(data.message_type).label }}
        </Badge>
      </template>
    </PageTitle>
    <GoBackButton subject="messages" :fallback-to="{ name: 'recruitment-messages' }" />

    <AppLoader v-if="isLoading" subject="message details" />
    <AppError
      v-else-if="error"
      :error="error"
      :title="error.statusCode === 404 ? 'Message not found' : 'Failed to load message details'"
      :to="error.statusCode === 404 ? { name: 'recruitment-messages' } : undefined"
      :action-text="error.statusCode === 404 ? 'Back to messages' : undefined"
    />
    <AppEmpty v-else-if="!data" subject="message details" />
    <template v-else>
      <MessageDetailErrorAlert :error-message="errorMessage" :provider-error-code="data.sms_provider_error_code" />
      <MessageDetailAdminSections v-if="data?.role === 'admin'" :key="data.id" :data="data" />

      <Card>
        <CardHeader>
          <CardTitle class="text-base">Content</CardTitle>
        </CardHeader>
        <CardContent>
          <MessageDetailContent
            :channel="data.channel"
            :content="data.content"
            :sms-opt-out-line="data.sms_opt_out_line"
            :sms-link-minted="data.sms_link_target !== null"
          />
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle class="text-base">Metadata</CardTitle>
        </CardHeader>
        <CardContent class="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <LabeledValueIcon label="Sent by" :icon="UserRoundIcon">
            <InlineEntityUser v-if="data.sent_by_user" :user="data.sent_by_user" :user-id="data.sent_by_user.id" />
            <span v-else>Recruitment AI</span>
          </LabeledValueIcon>
          <LabeledEntityDate :date="data.created_at" label="Created at" />
          <LabeledEntityDate :date="data.sent_at ?? undefined" label="Sent at" />
          <LabeledEntityDate :date="data.scheduled_send_at ?? undefined" label="Scheduled" />
          <LabeledValueIcon label="Referral" :icon="UserPlusIcon" :value="data.is_referral ? 'Yes' : 'No'" />
          <template v-if="data.channel === 'sms'">
            <LabeledValueIcon label="SMS destination" :icon="SmartphoneIcon" :value="data.sms_destination ?? '—'" />
            <LabeledValueIcon
              v-if="data.sms_provider_status"
              label="Provider status"
              :icon="ActivityIcon"
              :value="data.sms_provider_status"
            />
            <LabeledValueIcon
              v-if="data.sms_provider_error_code"
              label="Provider error code"
              :icon="ActivityIcon"
              :value="data.sms_provider_error_code"
            />
            <LabeledValueIcon
              v-if="data.sms_link_target"
              label="Link target"
              :icon="LinkIcon"
              :value="data.sms_link_target"
            />
          </template>
        </CardContent>
      </Card>

      <Card v-if="data.message_type === 'project'">
        <CardHeader>
          <CardTitle class="text-base">Campaign</CardTitle>
        </CardHeader>
        <CardContent>
          <LabeledEntityCampaign :campaign="data.campaign" />
        </CardContent>
      </Card>

      <Card v-if="data.mentioned_projects?.length">
        <CardHeader>
          <CardTitle class="text-base">Mentions</CardTitle>
        </CardHeader>
        <CardContent class="flex flex-wrap gap-1">
          <NuxtLink
            v-for="project in data.mentioned_projects"
            :key="project.id"
            :to="{ name: 'projects-id', params: { id: project.id } }"
            class="text-xs bg-muted text-primary px-2 py-0.5 rounded-full hover:underline"
          >
            {{ project.name }} →
          </NuxtLink>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle class="text-base">Contact</CardTitle>
        </CardHeader>
        <CardContent class="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <LabeledEntityContact :contact="data.staffing_contact" label="Name" />
          <LabeledValueIcon label="Email" :icon="AtSignIcon" :value="data.email" />
        </CardContent>
      </Card>

      <Card v-if="data.status_history?.length">
        <CardHeader>
          <CardTitle class="text-base">Status History</CardTitle>
        </CardHeader>
        <CardContent>
          <ol class="relative border-s border-border ms-2">
            <li v-for="(entry, index) in data.status_history" :key="index" class="mb-4 last:mb-0 ms-4">
              <div
                class="absolute -start-1.5 mt-1 h-3 w-3 rounded-full border border-background"
                :class="getMessageStatus(entry.status).dotColor"
              />
              <Badge :variant="getMessageStatus(entry.status).variant" size="sm" class="mb-0.5">
                {{ getMessageStatus(entry.status).label }}
              </Badge>
              <p class="text-xs text-muted-foreground">
                {{ formatDateTzToFormat(entry.updated_at, 'MM/dd/yyyy, hh:mm aaa', timezone) }}
              </p>
            </li>
          </ol>
        </CardContent>
      </Card>

      <Card v-if="relatedMessages.length > 0">
        <CardHeader>
          <CardTitle class="text-base">Other Messages to This Contact</CardTitle>
        </CardHeader>
        <CardContent class="flex flex-col gap-2">
          <NuxtLink
            v-for="msg in relatedMessages"
            :key="msg.id"
            :to="{ name: 'recruitment-messages-id', params: { id: msg.id } }"
            class="flex flex-col sm:flex-row sm:items-center gap-1 sm:gap-2 p-2 border rounded-md hover:bg-muted/50"
          >
            <div class="flex items-center gap-2 shrink-0">
              <Badge :variant="getChannel(msg.channel).variant" size="sm">
                {{ getChannel(msg.channel).label }}
              </Badge>
              <Badge :variant="getMessageStatus(msg.effective_status).variant" size="sm">
                {{ getMessageStatus(msg.effective_status).label }}
              </Badge>
              <Badge :variant="getMessageType(msg.message_type).variant" size="sm">
                {{ getMessageType(msg.message_type).label }}
              </Badge>
              <span class="text-xs text-muted-foreground sm:hidden ml-auto">
                {{ msg.sent_at ? formatDateTzToFormat(msg.sent_at, 'MM/dd/yyyy, hh:mm aaa', timezone) : '—' }}
              </span>
            </div>
            <span class="text-sm flex-1 truncate">{{ msg.subject ?? `${getChannel(msg.channel).label} message` }}</span>
            <span class="text-xs text-muted-foreground hidden sm:inline">
              {{ msg.sent_at ? formatDateTzToFormat(msg.sent_at, 'MM/dd/yyyy, hh:mm aaa', timezone) : '—' }}
            </span>
          </NuxtLink>
          <NuxtLink
            :to="{ name: 'recruitment-messages', query: { search_query: data.email } }"
            class="text-sm text-primary hover:underline mt-2"
          >
            View All Messages to This Contact →
          </NuxtLink>
        </CardContent>
      </Card>
    </template>
  </section>
</template>

<script setup lang="ts">
import {
  getRecruitmentMessageDetails,
  getStaffingContactInteractionList,
  type GetRecruitmentMessageDetailsResponse,
  type GetStaffingContactInteractionListResponse,
} from '~/client';
import { ActivityIcon, AtSignIcon, LinkIcon, SmartphoneIcon, UserPlusIcon, UserRoundIcon } from 'lucide-vue-next';
import { Card, CardHeader, CardTitle, CardContent } from '~/components/ui/card';
import { Badge } from '~/components/ui/badge';
import { getMessageStatus } from '~/constants/recruitment/messageStatusConfig';
import { getMessageType } from '~/constants/recruitment/messageTypeConfig';
import { getChannel } from '~/constants/recruitment/channelStrategyConfig';

definePageMeta({
  roles: ['admin', 'manager'],
  backLabel: 'message',
});

const route = useRoute('recruitment-messages-id');
const messageId = computed(() => route.params.id);

const { data, error, isLoading } = useQuery({
  key: () => ['recruitment-message', messageId.value],
  query: (): Promise<GetRecruitmentMessageDetailsResponse> =>
    getRecruitmentMessageDetails({ composable: '$fetch', path: { message_id: messageId.value } }),
  enabled: () => !!messageId.value,
});

const { data: relatedData } = useQuery({
  key: () => ['staffing-contact-interactions', data.value?.email ?? ''],
  query: (): Promise<GetStaffingContactInteractionListResponse> =>
    getStaffingContactInteractionList({
      composable: '$fetch',
      path: { email: data.value!.email },
      query: { size: 6 },
    }),
  enabled: () => !!data.value?.email,
});

const relatedMessages = computed(() => {
  const items = relatedData.value?.items ?? [];
  return items.filter((m) => m.id !== data.value?.id).slice(0, 5);
});

const { timezone } = useUserRole();

// Only the admin response shape carries the internal error reason; the manager shape has the carrier code alone.
const errorMessage = computed(() => (data.value?.role === 'admin' ? data.value.error_message : null));

// SMS rows carry no subject; fall back to a channel label so the title is never an empty/blank line.
const pageTitle = computed(() => {
  const message = data.value;
  if (!message) return 'Message';
  return message.subject ?? `${getChannel(message.channel).label} message`;
});

useHead({
  title: pageTitle,
});
</script>
