import type { BadgeVariants } from '~/components/ui/badge';

// Mirror of backend RecruitmentMessageErrorCode. Not in generated client because the enum
// gets serialized into the `error_message` string field, not its own schema.
type RecruitmentMessageErrorCode =
  | 'gemini_failed'
  | 'missing_generation_context'
  | 'prompt_render_failed'
  | 'unexpected_generation_error'
  | 'generation_retries_exceeded'
  | 'mailersend_rejected'
  | 'mailersend_suppressed'
  | 'mailersend_validation_failed'
  | 'rate_limit_retries_exceeded'
  | 'unconfirmed_retries_exceeded'
  | 'sender_disabled'
  | 'max_age_exceeded'
  | 'suppressed_before_send'
  | 'contact_now_busy'
  | 'kill_switch_disabled'
  | 'campaign_paused'
  | 'no_sms_destination'
  | 'sms_opted_out'
  | 'twilio_rejected'
  | 'sms_body_invalid'
  | 'sms_send_unconfirmed';

interface MessageErrorCodeEntry {
  label: string;
  variant: BadgeVariants;
  description: string;
}

export const messageErrorCodeConfig: Record<RecruitmentMessageErrorCode, MessageErrorCodeEntry> = {
  gemini_failed: {
    label: 'Gemini Failed',
    variant: 'destructive',
    description: 'Gemini did not return a usable response.',
  },
  missing_generation_context: {
    label: 'Missing Generation Context',
    variant: 'destructive',
    description: 'The data needed to build the prompt could not be assembled, so generation was skipped.',
  },
  prompt_render_failed: {
    label: 'Prompt Render Failed',
    variant: 'destructive',
    description: 'The prompt template failed to render from the generation context.',
  },
  unexpected_generation_error: {
    label: 'Unexpected Generation Error',
    variant: 'destructive',
    description: 'Generation crashed with an unexpected error.',
  },
  generation_retries_exceeded: {
    label: 'Generation Retries Exceeded',
    variant: 'warning',
    description: 'Generation kept getting stuck and the recovery retries ran out.',
  },
  mailersend_rejected: {
    label: 'MailerSend Rejected',
    variant: 'destructive',
    description: 'MailerSend refused the batch instead of accepting it for delivery.',
  },
  mailersend_suppressed: {
    label: 'MailerSend Suppressed',
    variant: 'warning',
    description: 'MailerSend reported the recipient as suppressed, so this message was not delivered.',
  },
  mailersend_validation_failed: {
    label: 'MailerSend Validation Failed',
    variant: 'destructive',
    description: 'MailerSend rejected this recipient in the batch as a validation error.',
  },
  rate_limit_retries_exceeded: {
    label: 'Rate Limit Retries Exceeded',
    variant: 'warning',
    description: 'MailerSend kept rate-limiting the send and the retry attempts ran out.',
  },
  unconfirmed_retries_exceeded: {
    label: 'Unconfirmed Retries Exceeded',
    variant: 'warning',
    description: 'MailerSend never confirmed the send and the retry attempts ran out.',
  },
  sender_disabled: {
    label: 'Sender Disabled',
    variant: 'default',
    description:
      'The sending integration (MailerSend for email, Twilio for SMS) is turned off, so the send was skipped.',
  },
  max_age_exceeded: {
    label: 'Max Age Exceeded',
    variant: 'default',
    description: 'The message sat unsent past its maximum age and was swept to failed.',
  },
  suppressed_before_send: {
    label: 'Suppressed Before Send',
    variant: 'warning',
    description: 'The contact opted out, bounced, or was marked do-not-hire before the send, so it was skipped.',
  },
  contact_now_busy: {
    label: 'Contact Now Busy',
    variant: 'default',
    description: 'The contact became busy on another project before this project message could send.',
  },
  kill_switch_disabled: {
    label: 'Kill Switch Disabled',
    variant: 'default',
    description:
      'Automated recruitment sending is turned off by its kill switch, so this autonomous message was skipped.',
  },
  campaign_paused: {
    label: 'Campaign Paused',
    variant: 'default',
    description: "The project's campaign was paused, so this autonomous message was skipped.",
  },
  no_sms_destination: {
    label: 'No SMS Destination',
    variant: 'destructive',
    description: 'The contact has no phone number to text.',
  },
  sms_opted_out: {
    label: 'SMS Opted Out',
    variant: 'warning',
    description:
      'The recipient texted STOP (or Twilio reported the number as opted out), so no more texts go to this number.',
  },
  twilio_rejected: {
    label: 'Twilio Rejected',
    variant: 'destructive',
    description: 'Twilio refused the message - usually an invalid, landline, or unreachable number.',
  },
  sms_body_invalid: {
    label: 'SMS Body Invalid',
    variant: 'destructive',
    description:
      'The assembled text failed its safety checks (missing link code, characters SMS cannot carry, or over the two-segment budget), so it was not sent.',
  },
  sms_send_unconfirmed: {
    label: 'SMS Send Unconfirmed',
    variant: 'warning',
    description:
      'Twilio never confirmed receiving the send. It is not retried - that could deliver a duplicate text - and the sweeper closes it out.',
  },
};

export function getMessageErrorCode(code: string): MessageErrorCodeEntry | null {
  return messageErrorCodeConfig[code as RecruitmentMessageErrorCode] ?? null;
}
