<template>
  <div class="grid grid-cols-1 sm:grid-cols-2 gap-4">
    <LabeledValue v-for="(item, index) in info" :key="index" :label="item.label" :value="item.value" />

    <LabeledValue label="Description">
      <span class="whitespace-pre-wrap text-wrap">{{ project.description || '—' }}</span>
    </LabeledValue>

    <LabeledValue label="Public URL">
      <a
        v-if="project.public_url"
        :href="project.public_url"
        target="_blank"
        rel="noopener"
        class="text-primary hover:underline break-all"
      >
        {{ project.public_url }}
      </a>
      <span v-else class="text-muted-foreground">—</span>
    </LabeledValue>

    <LabeledEntityProject :project="{ id: project.id, name: project.name }" />
  </div>
</template>

<script setup lang="ts">
import type { ProjectSnapshot } from '~/client';
import { formatUTCDateString } from '~/utils/formatDateToFormat';

const props = defineProps<{ project: ProjectSnapshot }>();

const info = computed(() => [
  { label: 'Type', value: props.project.project_type },
  { label: 'Locations', value: props.project.locations || '—' },
  { label: 'Start Date', value: formatUTCDateString(props.project.start_date, 'MM/dd/yyyy') },
  { label: 'End Date', value: formatUTCDateString(props.project.end_date, 'MM/dd/yyyy') },
]);
</script>
