<template>
  <LabeledValueIcon
    :to="{ name: 'staffing-resources-email', params: { email: contact.email } }"
    :label="label || 'Contact'"
    :icon="UserRoundIcon"
  >
    <div class="flex flex-row gap-2 flex-wrap items-center">
      <p class="font-medium line-clamp-1">{{ contactName }}</p>
      <Badge :variant="getRecruitmentStatus(contact.recruitment_status).variant" size="sm">
        {{ getRecruitmentStatus(contact.recruitment_status).label }}
      </Badge>
    </div>
  </LabeledValueIcon>
</template>
<script setup lang="ts">
import { UserRoundIcon } from 'lucide-vue-next';
import LabeledValueIcon from '~/components/common/LabeledValueIcon.vue';
import type { StaffingContactShortInfo } from '~/client';
import { getRecruitmentStatus } from '~/constants/staffing-contacts/recruitmentStatusConfig';

const props = defineProps<{
  contact: StaffingContactShortInfo;
  label?: string;
}>();

const contactName = computed(
  () => [props.contact.first_name, props.contact.last_name].filter(Boolean).join(' ') || props.contact.email
);
</script>
